// Typed keys and ICU arguments for next-intl, from the English catalog: a
// wrong key or a missing argument fails `tsc`. The `.d.json.ts` next to
// en.json (generated by next dev, build and typegen) carries the literal
// strings that make argument checks possible.
import type { Locale } from "@repo/i18n/config";
import type en from "@/messages/en.json";

declare module "next-intl" {
  interface AppConfig {
    Locale: Locale;
    Messages: typeof en;
  }
}
